package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

type User struct {
	ID        int    `json:"id"`
	Username  string `json:"username"`
	Email     string `json:"email"`
	Role      string `json:"role"`
	IsAdmin   bool   `json:"is_admin"`
	CanExport bool   `json:"can_export"`
}

var users = map[int]*User{
	1: {ID: 1, Username: "alice", Email: "alice@corp.io", Role: "viewer", IsAdmin: false, CanExport: false},
	2: {ID: 2, Username: "bob", Email: "bob@corp.io", Role: "viewer", IsAdmin: false, CanExport: false},
}

// UpdateProfile allows users to update their profile fields
func UpdateProfile(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Simulate auth - in production this comes from JWT
	userID := 1

	user, exists := users[userID]
	if !exists {
		http.Error(w, "User not found", 404)
		return
	}

	// Mass assignment vulnerability: decode all JSON fields directly into User struct
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(user); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Preserve ID
	user.ID = userID

	log.Printf("Updated user %d: role=%s is_admin=%v can_export=%v", user.ID, user.Role, user.IsAdmin, user.CanExport)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(user)
}

// ExportData runs a network diagnostic and exports data (admin only)
func ExportData(w http.ResponseWriter, r *http.Request) {
	userID := 1
	user := users[userID]

	if !user.IsAdmin || !user.CanExport {
		http.Error(w, "Forbidden: admin with export permission required", 403)
		return
	}

	// Uses raw socket for network health check before export
	target := r.URL.Query().Get("target")
	if target == "" {
		target = "127.0.0.1"
	}

	// Validate target loosely
	if strings.ContainsAny(target, ";|&$`") {
		http.Error(w, "Invalid target", 400)
		return
	}

	// ping uses raw sockets (CAP_NET_RAW)
	cmd := exec.Command("ping", "-c", "1", "-W", "1", target)
	output, err := cmd.CombinedOutput()
	if err != nil {
		log.Printf("Health check failed: %v", err)
		// Fallback: try reading /proc/net/tcp (requires CAP_SYS_ADMIN in some contexts)
		data, ferr := os.ReadFile("/proc/net/tcp")
		if ferr != nil {
			http.Error(w, "Network diagnostics unavailable - export blocked", 503)
			return
		}
		output = data
	}

	w.Header().Set("Content-Type", "application/json")
	resp := map[string]interface{}{
		"status":      "export_ready",
		"health":      string(output),
		"records":     1024,
		"export_path": "/data/export_2024.csv",
	}
	json.NewEncoder(w).Encode(resp)
}

func HealthCheck(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "{\"status\": \"ok\"}")
}

func main() {
	http.HandleFunc("/health", HealthCheck)
	http.HandleFunc("/api/v1/profile", UpdateProfile)
	http.HandleFunc("/api/v1/export", ExportData)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting user-service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
